// View-plane distance at uv, or a negative number where there is no surface.
fn viewDepth(uv: vec2f) -> f32 {
  let d = textureLoad(inputTexture1, depthTexel(uv), 0).r;
  return select(d * params.far, -1.0, d >= 0.9999 || d <= 0.0);
}

fn worldAt(v: View, uv: vec2f, z: f32) -> vec3f {
  let ray = rayAt(v, uv);
  return params.eye + ray * (z / max(dot(ray, v.forward), 1e-4));
}

// World point → (uv, view-plane distance); z ≤ 0 means behind the camera.
fn project(v: View, world: vec3f) -> vec3f {
  let rel = world - params.eye;
  let z = dot(rel, v.forward);
  let x = dot(rel, v.right) / (max(z, 1e-4) * v.tanHalf * v.aspect);
  let y = dot(rel, v.up) / (max(z, 1e-4) * v.tanHalf);
  return vec3f(x * 0.5 + 0.5, 0.5 - y * 0.5, z);
}

fn ignHash(pixel: vec2f) -> f32 {
  return fract(52.9829189 * fract(dot(pixel, vec2f(0.06711056, 0.00583715))));
}

// The ghost table is parameters (ratio, radius, rim, fill, strength: one vec4 component per
// ghost; T1407b lights), so a take can drop or reshape a ghost; the colours stay fixed.
const GHOSTS: u32 = 4u;
const G_COLOR = array<vec3f, 4>(vec3f(0.85, 0.9, 1.0), vec3f(0.7, 0.8, 0.95), vec3f(1.0, 0.55, 0.3), vec3f(0.6, 0.85, 1.0));

fn ring(d: f32, radius: f32, rim: f32, fill: f32) -> f32 {
  let edge = exp(-pow((d - radius) / rim, 2.0));
  let disc = (1.0 - smoothstep(radius - rim, radius + rim * 0.5, d)) * fill;
  return edge + disc;
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let base = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let v = makeView();
  let at = project(v, params.lamp);
  if (at.z <= 0.0) { return base; }
  // How much of the source still shows (the head eclipses most of it): the bright pass summed
  // over a patch round where it stands.
  let aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  var seen = vec3f(0.0);
  for (var j = -3; j <= 3; j = j + 1) {
    for (var i = -3; i <= 3; i = i + 1) {
      let o = vec2f(f32(i) / aspect, f32(j)) * 0.012;
      seen = seen + textureSampleLevel(inputTexture1, inputSampler, clamp(at.xy + o, vec2f(0.0), vec2f(1.0)), 0.0).rgb;
    }
  }
  let power = dot(seen / 49.0, vec3f(0.2126, 0.7152, 0.0722));
  var add = vec3f(0.0);
  for (var g = 0u; g < GHOSTS; g = g + 1u) {
    let centre = vec2f(0.5) + (at.xy - vec2f(0.5)) * params.ratio[g];
    let q = (uv - centre) * vec2f(aspect, 1.0);
    let d = length(q);
    // dispersion: red a little larger than blue
    let r = ring(d, params.radius[g] * 1.012, params.rim[g], params.fill[g]);
    let gg = ring(d, params.radius[g], params.rim[g], params.fill[g]);
    let b = ring(d, params.radius[g] * 0.988, params.rim[g], params.fill[g]);
    add = add + vec3f(r, gg, b) * G_COLOR[g] * params.tint * params.strength[g];
  }
  return vec4f(base.rgb + add * power * params.gain, base.a);
}

