@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

// T1383b: the camera's right vector with its ROLL — world up turned about the view axis by
// roll degrees (Rodrigues, right-handed about the camera's +z: the angle is negated about forward),
// exactly as camera.ts guardedRolledUp builds the render's view (T1433b).
fn rolledRight(forward: vec3f, rollDeg: f32) -> vec3f {
  var up = select(vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0), abs(forward.y) > 0.999);
  let t = radians(-rollDeg);
  up = up * cos(t) + cross(forward, up) * sin(t) + forward * dot(forward, up) * (1.0 - cos(t));
  return normalize(cross(forward, up));
}

struct View {
  forward: vec3f,
  right: vec3f,
  up: vec3f,
  tanHalf: f32,
  aspect: f32,
};

fn makeView() -> View {
  var v: View;
  v.forward = normalize(params.aim - params.eye);
  v.right = rolledRight(v.forward, params.roll);
  v.up = cross(v.right, v.forward);
  v.tanHalf = tan(radians(params.fov) * 0.5);
  v.aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  return v;
}

fn rayAt(v: View, uv: vec2f) -> vec3f {
  let ndc = vec2f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
  return normalize(v.forward + v.right * ndc.x * v.tanHalf * v.aspect + v.up * ndc.y * v.tanHalf);
}

fn depthTexel(uv: vec2f) -> vec2i {
  let size = vec2f(textureDimensions(inputTexture1));
  return clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1));
}

// View-plane distance at uv, or a negative number where there is no surface.
fn viewDepth(uv: vec2f) -> f32 {
  let d = textureLoad(inputTexture1, depthTexel(uv), 0).r;
  return select(d * params.far, -1.0, d >= 0.9999 || d <= 0.0);
}

fn worldAt(v: View, uv: vec2f, z: f32) -> vec3f {
  let ray = rayAt(v, uv);
  return params.eye + ray * (z / max(dot(ray, v.forward), 1e-4));
}

// World point → (uv, view-plane distance); z ≤ 0 means behind the camera.
fn project(v: View, world: vec3f) -> vec3f {
  let rel = world - params.eye;
  let z = dot(rel, v.forward);
  let x = dot(rel, v.right) / (max(z, 1e-4) * v.tanHalf * v.aspect);
  let y = dot(rel, v.up) / (max(z, 1e-4) * v.tanHalf);
  return vec3f(x * 0.5 + 0.5, 0.5 - y * 0.5, z);
}

fn ignHash(pixel: vec2f) -> f32 {
  return fract(52.9829189 * fract(dot(pixel, vec2f(0.06711056, 0.00583715))));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let base = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let v = makeView();
  let ray = rayAt(v, uv);
  let toLamp = params.lamp - params.eye;
  let along = dot(toLamp, ray);
  if (along <= 0.0) { return base; }
  let miss = length(toLamp - ray * along);
  let face = 1.0 - smoothstep(params.size * 0.85, params.size, miss);
  if (face <= 0.0) { return base; }
  let z = viewDepth(uv);
  let lampZ = dot(toLamp, v.forward);
  if (z > 0.0 && z < lampZ) { return base; }
  return vec4f(base.rgb + params.tint * params.radiance * face, base.a);
}

struct Params {
  k: f32, // @default 0.13  Barrel distortion (height units², normalised at the side edges).
  edgeBlur: f32, // @default 0.018  Edge smear at the side edges, fraction of the frame height.
  swirl: f32, // @default 0.7  0 radial .. 1 tangential edge smear.
  aberration: f32, // @default 0.004  Lateral colour at the side edges, fraction of the radius.
  vignette: f32, // @default 0.5  Darkening at the corners.
};
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
const TAPS: i32 = 16;

fn ignHash(pixel: vec2f) -> f32 {
  return fract(52.9829189 * fract(dot(pixel, vec2f(0.06711056, 0.00583715))));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let size = vec2f(textureDimensions(inputTexture));
  let aspect = size.x / size.y;
  let scaleXY = vec2f(aspect, 1.0);
  let c = (uv - vec2f(0.5)) * scaleXY;
  let r2 = dot(c, c);
  let e2 = aspect * aspect * 0.25;
  let src = c * (1.0 + params.k * r2) / (1.0 + params.k * e2);
  // Edge smear: nothing in the centre third, growing to edgeBlur at the side edges.
  let edge = smoothstep(0.08, 1.0, r2 / e2);
  let radial = normalize(src + vec2f(1e-5));
  let tangent = vec2f(-radial.y, radial.x);
  let dir = normalize(mix(radial, tangent, params.swirl)) * params.edgeBlur * edge * edge;
  let jitter = ignHash(uv * size) - 0.5;
  var sum = vec3f(0.0);
  for (var i = 0; i < TAPS; i = i + 1) {
    let t = (f32(i) + 0.5 + jitter) / f32(TAPS) - 0.5;
    let p = src + dir * t;
    let ca = p * params.aberration * edge;
    let rch = textureSampleLevel(inputTexture, inputSampler, (p + ca) / scaleXY + 0.5, 0.0).r;
    let gch = textureSampleLevel(inputTexture, inputSampler, p / scaleXY + 0.5, 0.0).g;
    let bch = textureSampleLevel(inputTexture, inputSampler, (p - ca) / scaleXY + 0.5, 0.0).b;
    sum = sum + vec3f(rch, gch, bch);
  }
  var color = sum / f32(TAPS);
  let q = (uv - vec2f(0.5)) * 2.0;
  let vr = dot(q * vec2f(1.0, 0.8), q * vec2f(1.0, 0.8));
  color = color * mix(1.0, 1.0 - smoothstep(0.35, 1.6, vr), params.vignette);
  return vec4f(color, 1.0);
}

struct Params {
  mist: f32, // @default 0  Share of the near glow mixed into the picture (halation, bloom), in linear light.
  mistWide: f32, // @default 0  Share of the wide glow mixed in: the haze veil that lifts the dark round every light.
  toe: f32, // @default 1  Gamma on display level before the curve (< 1 opens the shadows).
  contrast: f32, // @default 1  Slope around the pivot (< 1 is flatter).
  pivot: f32, // @default 0.45  Display level the contrast turns about.
  lift: f32, // @default 0  Where black lands (display level): the flat veil.
  white: f32, // @default 1  Where white lands (display level): the washed top.
  saturation: f32, // @default 1  Chroma kept in the mids and highlights.
  shadowSaturation: f32, // @default 1  Chroma kept in the shadows.
  shadowTint: vec3f, // @default 0  Added to the shadows (display level).
  midTint: vec3f, // @default 0  Added to the mids.
  highlightTint: vec3f, // @default 0  Added to the highlights.
  grain: f32, // @default 0  Grain amount (the grade's formula: heavier in the blacks, a new pattern every frame).
  grainSize: f32, // @default 1.3  Grain cell size in pixels of the render.
};
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;

// More textures are bound unfilterable: bilinear by hand.
fn bilerp(t: texture_2d<f32>, uv: vec2f) -> vec3f {
  let size = vec2f(textureDimensions(t));
  let p = uv * size - 0.5;
  let i = floor(p);
  let f = p - i;
  let hi = vec2i(size) - vec2i(1);
  let a = vec2i(i);
  let c00 = textureLoad(t, clamp(a, vec2i(0), hi), 0).rgb;
  let c10 = textureLoad(t, clamp(a + vec2i(1, 0), vec2i(0), hi), 0).rgb;
  let c01 = textureLoad(t, clamp(a + vec2i(0, 1), vec2i(0), hi), 0).rgb;
  let c11 = textureLoad(t, clamp(a + vec2i(1, 1), vec2i(0), hi), 0).rgb;
  return mix(mix(c00, c10, f.x), mix(c01, c11, f.x), f.y);
}

// The Output encodes sRGB, so "display level" here is exactly the sRGB value the viewer sees
// (a 2.2 power instead put a 0.022 lift at level 1 of 255, not 5.6: the toes part ways near black).
fn toDisplay(l: vec3f) -> vec3f {
  return select(1.055 * pow(l, vec3f(1.0 / 2.4)) - 0.055, 12.92 * l, l <= vec3f(0.0031308));
}

fn toLinear(d: vec3f) -> vec3f {
  return select(pow((d + 0.055) / 1.055, vec3f(2.4)), d / 12.92, d <= vec3f(0.04045));
}

fn luma(c: vec3f) -> f32 {
  return dot(c, vec3f(0.2126, 0.7152, 0.0722));
}

fn grainHash(p: vec3f) -> f32 {
  var q = fract(p * vec3f(0.1031, 0.1030, 0.0973));
  q = q + dot(q, q.yxz + 33.33);
  return fract((q.x + q.y) * q.z);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let lin = max(textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb, vec3f(0.0));
  let near = bilerp(inputTexture1, uv);
  let wide = bilerp(inputTexture2, uv);
  // the mist, in linear light: the lights' glow and the veil round them
  let m = lin * (1.0 - params.mist - params.mistWide) + near * params.mist + wide * params.mistWide;
  // the curve, on display level: toe, contrast about the pivot, then black and white land
  var c = pow(clamp(toDisplay(max(m, vec3f(0.0))), vec3f(0.0), vec3f(1.0)), vec3f(params.toe));
  c = clamp(params.pivot + (c - params.pivot) * params.contrast, vec3f(0.0), vec3f(1.0));
  c = params.lift + (params.white - params.lift) * c;
  // tone bands: a tint added to each
  let y0 = luma(c);
  let ws = 1.0 - smoothstep(0.04, 0.22, y0);
  let wh = smoothstep(0.35, 0.75, y0);
  let wm = clamp(1.0 - ws - wh, 0.0, 1.0);
  c = c + ws * params.shadowTint + wm * params.midTint + wh * params.highlightTint;
  let y = luma(c);
  c = vec3f(y) + (c - vec3f(y)) * mix(params.saturation, params.shadowSaturation, ws);
  // the film's one grain (render.ts adds it after the accumulation under --final, T1432b)
  let px = floor(uv * frameU.resolution / max(params.grainSize, 0.5));
  let n = grainHash(vec3f(px, frameU.absFrame)) + grainHash(vec3f(px + 17.0, frameU.absFrame * 1.7)) - 1.0;
  c = c + vec3f(n) * params.grain * (0.35 + 0.65 * (1.0 - luma(c)));
  c = clamp(c, vec3f(0.0), vec3f(1.0));
  return vec4f(toLinear(c), 1.0);
}

struct Params {
  gain: f32, // @default 1  Scales the downsampled picture.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  // one output texel's footprint in uv
  let foot = vec2f(abs(dpdx(uv).x), abs(dpdy(uv).y));
  var sum = vec3f(0.0);
  for (var j = 0; j < 4; j = j + 1) {
    for (var i = 0; i < 4; i = i + 1) {
      let o = (vec2f(f32(i), f32(j)) + 0.5) / 4.0 - 0.5;
      sum = sum + max(textureSampleLevel(inputTexture, inputSampler, uv + o * foot, 0.0).rgb, vec3f(0.0));
    }
  }
  return vec4f(sum / 16.0 * params.gain, 1.0);
}

struct Params {
  bloom: f32, // @default 0.3  Bloom glow added back.
  halo: f32, // @default 1  Halo ring added back.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let base = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let b = textureSampleLevel(inputTexture1, inputSampler, uv, 0.0).rgb;
  let h = textureSampleLevel(inputTexture2, inputSampler, uv, 0.0).rgb;
  return vec4f(base.rgb + b * params.bloom + h * params.halo, base.a);
}

