    case 0u: { return ctx.params.pelvis; }
    case 1u: { return ctx.params.spine; }
    case 2u: { return ctx.params.chest; }
    case 3u: { return ctx.params.neck; }
    case 4u: { return ctx.params.head; }
    case 5u: { return ctx.params.shoulderL; }
    case 6u: { return ctx.params.upperarmL; }
    case 7u: { return ctx.params.forearmL; }
    case 8u: { return ctx.params.handL; }
    case 9u: { return ctx.params.thumb1L; }
    case 10u: { return ctx.params.thumb2L; }
    case 11u: { return ctx.params.thumb3L; }
    case 12u: { return ctx.params.index1L; }
    case 13u: { return ctx.params.index2L; }
    case 14u: { return ctx.params.index3L; }
    case 15u: { return ctx.params.middle1L; }
    case 16u: { return ctx.params.middle2L; }
    case 17u: { return ctx.params.middle3L; }
    case 18u: { return ctx.params.ring1L; }
    case 19u: { return ctx.params.ring2L; }
    case 20u: { return ctx.params.ring3L; }
    case 21u: { return ctx.params.pinky1L; }
    case 22u: { return ctx.params.pinky2L; }
    case 23u: { return ctx.params.pinky3L; }
    case 24u: { return ctx.params.shoulderR; }
    case 25u: { return ctx.params.upperarmR; }
    case 26u: { return ctx.params.forearmR; }
    case 27u: { return ctx.params.handR; }
    case 28u: { return ctx.params.thumb1R; }
    case 29u: { return ctx.params.thumb2R; }
    case 30u: { return ctx.params.thumb3R; }
    case 31u: { return ctx.params.index1R; }
    case 32u: { return ctx.params.index2R; }
    case 33u: { return ctx.params.index3R; }
    case 34u: { return ctx.params.middle1R; }
    case 35u: { return ctx.params.middle2R; }
    case 36u: { return ctx.params.middle3R; }
    case 37u: { return ctx.params.ring1R; }
    case 38u: { return ctx.params.ring2R; }
    case 39u: { return ctx.params.ring3R; }
    case 40u: { return ctx.params.pinky1R; }
    case 41u: { return ctx.params.pinky2R; }
    case 42u: { return ctx.params.pinky3R; }
    case 43u: { return ctx.params.thighL; }
    case 44u: { return ctx.params.shinL; }
    case 45u: { return ctx.params.footL; }
    case 46u: { return ctx.params.thighR; }
    case 47u: { return ctx.params.shinR; }
    case 48u: { return ctx.params.footR; }
