  }
}

fn euler(e: vec3f) -> mat3x3f {
  let cx = cos(e.x); let sx = sin(e.x);
  let cy = cos(e.y); let sy = sin(e.y);
  let cz = cos(e.z); let sz = sin(e.z);
  let rx = mat3x3f(vec3f(1.0, 0.0, 0.0), vec3f(0.0, cx, sx), vec3f(0.0, -sx, cx));
  let ry = mat3x3f(vec3f(cy, 0.0, -sy), vec3f(0.0, 1.0, 0.0), vec3f(sy, 0.0, cy));
  let rz = mat3x3f(vec3f(cz, sz, 0.0), vec3f(-sz, cz, 0.0), vec3f(0.0, 0.0, 1.0));
  return rz * ry * rx;
}

// T1419b: a turn of t radians about the unit axis a (Rodrigues).
fn axisAngle(a: vec3f, t: f32) -> mat3x3f {
  let c = cos(t);
  let s = sin(t);
  let k = 1.0 - c;
  return mat3x3f(
    vec3f(c + a.x * a.x * k, a.y * a.x * k + a.z * s, a.z * a.x * k - a.y * s),
    vec3f(a.x * a.y * k - a.z * s, c + a.y * a.y * k, a.z * a.y * k + a.x * s),
    vec3f(a.x * a.z * k + a.y * s, a.y * a.z * k - a.x * s, c + a.z * a.z * k));
}

// T1419b: the hand knobs' turn of a finger bone, about rest axes measured from the heads.
fn fingerTurn(i: u32, ctx: PointCtx) -> mat3x3f {
  switch i {
    case 12u: { return axisAngle(vec3f(-0.88812, -0.41755, -0.19207), ctx.params.spreadL * 1.000) * axisAngle(vec3f(0.45014, -0.70587, -0.54692), ctx.params.curlL.x * 1.000); }
    case 13u: { return axisAngle(vec3f(0.44311, -0.66693, -0.59905), ctx.params.curlL.x * 1.150); }
    case 14u: { return axisAngle(vec3f(0.44311, -0.66693, -0.59905), ctx.params.curlL.x * 0.800); }
    case 15u: { return axisAngle(vec3f(-0.88812, -0.41755, -0.19207), ctx.params.spreadL * 0.150) * axisAngle(vec3f(0.40698, -0.52029, -0.75078), ctx.params.curlL.y * 1.000); }
    case 16u: { return axisAngle(vec3f(0.41815, -0.56065, -0.71472), ctx.params.curlL.y * 1.150); }
    case 17u: { return axisAngle(vec3f(0.41815, -0.56065, -0.71472), ctx.params.curlL.y * 0.800); }
    case 18u: { return axisAngle(vec3f(-0.88812, -0.41755, -0.19207), ctx.params.spreadL * -0.600) * axisAngle(vec3f(0.36496, -0.38670, -0.84692), ctx.params.curlL.z * 1.000); }
    case 19u: { return axisAngle(vec3f(0.38587, -0.45038, -0.80514), ctx.params.curlL.z * 1.150); }
    case 20u: { return axisAngle(vec3f(0.38587, -0.45038, -0.80514), ctx.params.curlL.z * 0.800); }
    case 21u: { return axisAngle(vec3f(-0.88812, -0.41755, -0.19207), ctx.params.spreadL * -1.200) * axisAngle(vec3f(0.33204, -0.29397, -0.89629), ctx.params.curlL.w * 1.000); }
    case 22u: { return axisAngle(vec3f(0.34927, -0.34151, -0.87257), ctx.params.curlL.w * 1.150); }
    case 23u: { return axisAngle(vec3f(0.34927, -0.34151, -0.87257), ctx.params.curlL.w * 0.800); }
    case 9u: { return axisAngle(vec3f(-0.41280, 0.90842, -0.06609), ctx.params.thumbL.y * 1.000) * axisAngle(vec3f(0.45536, -0.88249, 0.11772), ctx.params.thumbL.x * 0.350); }
    case 10u: { return axisAngle(vec3f(0.51944, -0.84496, -0.12737), ctx.params.thumbL.x * 0.800); }
    case 11u: { return axisAngle(vec3f(0.51944, -0.84496, -0.12737), ctx.params.thumbL.x * 0.900); }
    case 31u: { return axisAngle(vec3f(0.88812, -0.41755, -0.19207), ctx.params.spreadR * -1.000) * axisAngle(vec3f(0.45014, 0.70587, 0.54692), ctx.params.curlR.x * 1.000); }
    case 32u: { return axisAngle(vec3f(0.44311, 0.66693, 0.59905), ctx.params.curlR.x * 1.150); }
    case 33u: { return axisAngle(vec3f(0.44311, 0.66693, 0.59905), ctx.params.curlR.x * 0.800); }
    case 34u: { return axisAngle(vec3f(0.88812, -0.41755, -0.19207), ctx.params.spreadR * -0.150) * axisAngle(vec3f(0.40698, 0.52029, 0.75078), ctx.params.curlR.y * 1.000); }
    case 35u: { return axisAngle(vec3f(0.41815, 0.56065, 0.71472), ctx.params.curlR.y * 1.150); }
    case 36u: { return axisAngle(vec3f(0.41815, 0.56065, 0.71472), ctx.params.curlR.y * 0.800); }
    case 37u: { return axisAngle(vec3f(0.88812, -0.41755, -0.19207), ctx.params.spreadR * 0.600) * axisAngle(vec3f(0.36496, 0.38670, 0.84692), ctx.params.curlR.z * 1.000); }
    case 38u: { return axisAngle(vec3f(0.38587, 0.45038, 0.80514), ctx.params.curlR.z * 1.150); }
    case 39u: { return axisAngle(vec3f(0.38587, 0.45038, 0.80514), ctx.params.curlR.z * 0.800); }
    case 40u: { return axisAngle(vec3f(0.88812, -0.41755, -0.19207), ctx.params.spreadR * 1.200) * axisAngle(vec3f(0.33204, 0.29397, 0.89629), ctx.params.curlR.w * 1.000); }
    case 41u: { return axisAngle(vec3f(0.34927, 0.34151, 0.87257), ctx.params.curlR.w * 1.150); }
    case 42u: { return axisAngle(vec3f(0.34927, 0.34151, 0.87257), ctx.params.curlR.w * 0.800); }
    case 28u: { return axisAngle(vec3f(-0.41280, -0.90842, 0.06609), ctx.params.thumbR.y * 1.000) * axisAngle(vec3f(0.45536, 0.88249, -0.11772), ctx.params.thumbR.x * 0.350); }
    case 29u: { return axisAngle(vec3f(0.51944, 0.84496, 0.12737), ctx.params.thumbR.x * 0.800); }
    case 30u: { return axisAngle(vec3f(0.51944, 0.84496, 0.12737), ctx.params.thumbR.x * 0.900); }
    default: { return mat3x3f(vec3f(1.0, 0.0, 0.0), vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0)); }
  }
}

struct Xf {
  m: mat3x3f,
  t: vec3f,
};

// The bone's world transform: its own rotation about its head, then each ancestor's.
fn boneXf(bone: u32, ctx: PointCtx) -> Xf {
  var acc: Xf;
  acc.m = mat3x3f(vec3f(1.0, 0.0, 0.0), vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0));
  acc.t = vec3f(0.0);
  var j = i32(bone);
  // T1419b: pelvis → spine → chest → shoulder → upper arm → forearm → hand → three phalanges is
  // ten bones deep; the walk allows twelve.
  for (var level = 0u; level < 12u; level = level + 1u) {
    if (j < 0 || u32(j) >= BONES) { break; }
    let r = euler(boneAngles(u32(j), ctx)) * fingerTurn(u32(j), ctx);
    let h = BONE_HEAD[u32(j)];
    acc.m = r * acc.m;
    acc.t = r * (acc.t - h) + h;
    j = BONE_PARENT[u32(j)];
  }
  return acc;
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  // Linear-blend skinning over the four influences the decoder normalised to sum 1.
  var posed = vec3f(0.0);
  var bent = vec3f(0.0);
  var total = 0.0;
  for (var k = 0u; k < 4u; k = k + 1u) {
    let w = p.weights[k];
    if (w <= 0.0) { continue; }
    let x = boneXf(min(u32(p.joints[k] + 0.5), BONES - 1u), ctx);
    posed = posed + w * (x.m * p.position + x.t);
    bent = bent + w * (x.m * p.normal);
    total = total + w;
  }
  if (total <= 0.0) {
    // Nothing skins this vertex: it keeps its rest place.
    posed = p.position;
    bent = p.normal;
  } else {
    posed = posed / total;
  }
  let normal = normalize(bent);
  let c = cos(ctx.params.yaw);
  let s = sin(ctx.params.yaw);
  let turn = mat3x3f(vec3f(c, 0.0, -s), vec3f(0.0, 1.0, 0.0), vec3f(s, 0.0, c));
  q.position = ctx.params.place + turn * posed;
  q.normal = turn * normal;
  return q;
}

parameters.source:
// @use surface-detail
const CONTACT_COUNT: u32 = 0u;
const CONTACT = array<vec4f, 1>(vec4f(0.0, 0.0, -1.0, -1.0));
struct Params {
  headGain: f32, // @default 1  Headlight and DRL radiance multiplier.
  tubeGain: f32, // @default 1  LED tube radiance multiplier.
  tailGain: f32, // @default 1  Tail light radiance multiplier.
  wet: f32, // @default 0.4  Share of the floor that is damp and glossy.
  wetGloss: f32, // @default 0.22  Roughness of the damp patches.
  contactDepth: f32, // @default 0.93  How dark the floor gets under a parked car (0 off).
  contactReach: f32, // @default 1.1  How far the contact shadow reaches beyond the footprint, metres.
  dryGloss: f32, // @default 0.62  Roughness of the dry floor (worn concrete: past the reflections' cutoff).
  peel: f32, // @default 0.25  Orange-peel strength on the clear coat.
  silverAlbedo: f32, // @default 0.45  The hero's satin silver: its albedo (linear).
  silverRoughness: f32, // @default 0.3  The hero's satin silver: its roughness.
  silverMetallic: f32, // @default 0.2  The hero's satin silver: how metallic (a flake coat, mostly dielectric).
  cycAlbedo: f32, // @default 0.9  Albedo of the white cyc.
  ice: f32, // @default 0.075  The ice's own mirrored studio (jewel class only; T1407b closeups2).
};

fn classOf(s: SurfaceIn) -> u32 {
  return u32(s.attr.z * 64.0 + 0.5);
}

// Scratch lines: per 0.6 m cell, a random direction and offset; thin, broken, short.
fn scratchAt(w: vec2f, scale: f32, seed: u32) -> f32 {
  let q = w / scale;
  let cell = floor(q);
  let h = vec3f(unitFloat(hash3i(vec3i(vec3f(cell, 1.0)), seed)), unitFloat(hash3i(vec3i(vec3f(cell, 2.0)), seed + 7u)), unitFloat(hash3i(vec3i(vec3f(cell, 3.0)), seed + 13u)));
  let a = h.x * 3.14159;
  let local = q - cell - vec2f(0.5);
  let across = dot(local, vec2f(-sin(a), cos(a))) - (h.y - 0.5) * 0.6;
  let along = dot(local, vec2f(cos(a), sin(a)));
  let seg = smoothstep(0.45, 0.2, abs(along)) * step(0.35, h.z);
  return smoothstep(0.012, 0.0, abs(across)) * seg;
}

// CONTACT SHADOWS under the parked cars: each footprint (generated from the GLB, see
// contactFootprints) darkens the floor with a soft falloff — near black under the body, a
// short penumbra beyond it — the sky/room occlusion a screen-space pass cannot reach at 15 m.
fn contactShadow(q: vec2f, p: Params) -> f32 {
  var k = 1.0;
  for (var i = 0u; i < CONTACT_COUNT; i = i + 1u) {
    let f = CONTACT[i];
    let d = abs(q - f.xy) - f.zw;
    let outside = length(max(d, vec2f(0.0))) + min(max(d.x, d.y), 0.0);
    let shadow = pow(1.0 - smoothstep(-0.6, p.contactReach, outside), 1.6);
    k = k * (1.0 - shadow * p.contactDepth);
  }
  return k;
}

fn floorSurface(s: SurfaceIn, p: Params, o: SurfaceOut) -> SurfaceOut {
  // DRY, WORN warehouse concrete: satin, never glossy. A traffic-polished lane catches the
  // lamps as a soft sheen; scuffs, stains, aggregate and scratches break it everywhere.
  var r = o;
  let w = s.world;
  let large = detailFbm(vec3f(w.x * 0.18, 0.0, w.z * 0.18), 4, s.footprint);
  let mid = detailFbm(vec3f(w.x * 0.9, 5.0, w.z * 0.9), 4, s.footprint);
  let fine = detailFbm(w * 3.1, 5, s.footprint);
  let grit = detailFbm(w * 21.0, 3, s.footprint);
  let damp = smoothstep(1.0 - p.wet - 0.15, 1.0 - p.wet + 0.15, large.value + (fine.value - 0.5) * 0.25);
  // tyre scuffs and oil stains
  let scuff = smoothstep(0.6, 0.8, detailNoise(vec3f(w.x * 1.7, 0.0, w.z * 0.12)).value) * 0.45;
  let stain = smoothstep(0.62, 0.78, mid.value) * 0.35;
  // aggregate: a speckle of lighter and darker stones in the cement
  let stone = smoothstep(0.7, 0.85, grit.value) * 0.18 - smoothstep(0.3, 0.15, grit.value) * 0.12;
  let crack = smoothstep(0.006, 0.0, abs(detailNoise(vec3f(w.x * 0.9, 3.0, w.z * 0.9)).value - 0.5)) * 0.5;
  let scratches = max(scratchAt(w.xz, 0.6, 3u), scratchAt(w.xz + vec2f(0.21, 0.37), 0.35, 11u) * 0.6) * (1.0 - smoothstep(0.004, 0.02, s.footprint));
  let shade = (0.88 + 0.24 * fine.value + stone) * (0.85 + 0.3 * large.value);
  r.albedo = vec4f(o.albedo.rgb * shade * mix(1.0, 0.6, damp) * (1.0 - scuff * 0.5) * (1.0 - stain) * (1.0 - crack * 0.6) * (1.0 + scratches * 0.5) * contactShadow(w.xz, p), 1.0);
  // satin, never a mirror: polished where traffic ran, rough where it did not
  let polish = smoothstep(0.35, 0.75, large.value);
  r.roughness = clamp(mix(p.dryGloss + 0.12, p.dryGloss - 0.08, polish) + (grit.value - 0.5) * 0.1 + stain * 0.1 - scratches * 0.15, 0.3, 0.95);
  r.roughness = mix(r.roughness, p.wetGloss, damp);
  r.metallic = 0.0;
  r.normal = detailBump(s.normal, grit.gradient * 0.006 + fine.gradient * 0.015 + mid.gradient * 0.02, 1.0);
  return r;
}

fn brickSurface(s: SurfaceIn, o: SurfaceOut) -> SurfaceOut {
  var r = o;
  let w = s.world;
  let course = w.y / 0.075;
  let row = floor(course);
  let along = (w.x + w.z) / 0.23 + row * 0.5;
  let mortar = max(smoothstep(0.1, 0.0, fract(course)), smoothstep(0.06, 0.0, fract(along)));
  let n = detailFbm(w * 6.0, 4, s.footprint);
  r.albedo = vec4f(o.albedo.rgb * (0.7 + 0.6 * n.value) * mix(1.0, 1.6, mortar), 1.0);
  r.roughness = 0.9;
  r.normal = detailBump(s.normal, n.gradient * 0.01, 1.0);
  return r;
}

fn clearCoat(s: SurfaceIn, p: Params, o: SurfaceOut, roughness: f32) -> SurfaceOut {
  var r = o;
  let peel = detailFbm(s.world * 90.0, 2, s.footprint);
  r.roughness = roughness;
  r.normal = detailBump(s.normal, peel.gradient * 0.00045 * p.peel, 1.0);
  return r;
}

// ICE (T1407b closeups2): the chain, the bracelet, the pendant slab. As a pure mirror the ice
// showed only the dark room and read black in every shot; the reference's reads WHITE. A pavé
// is not a mirror: every stone returns light from inside, so it is (1) a bright white body the
// scene's lights light like a diffuse surface, and (2) a scatter of facets, each mirroring the
// set's lights as a glint. The room gives the facets nothing to mirror, so the ice carries its
// OWN reflected studio — a soft overhead box and a horizon band, seen through each stone's
// facet normal — as emission scaled by params.ice. It is the jewel-only environment gain: the
// Render's IBL (and so the skin) stays as low as each shot sets it.
fn jewel(s: SurfaceIn, p: Params, o: SurfaceOut) -> SurfaceOut {
  var r = o;
  // stones ~3 mm apart; each a facet tilted its own way
  let q = s.world * 330.0;
  let cell = floor(q);
  let h = vec3f(unitFloat(hash3i(vec3i(cell), 11u)), unitFloat(hash3i(vec3i(cell), 23u)), unitFloat(hash3i(vec3i(cell), 37u)));
  // facets finer than a pixel sparkle and crawl frame to frame: fade them to the smooth normal
  let resolved = 1.0 - smoothstep(0.0015, 0.005, s.footprint);
  // each stone ROUND in its cell (a cell's sphere cut by the surface), the metal of the setting
  // showing darker between them, so close up it reads as pavé rather than a mosaic of squares
  let seat = length(q - cell - vec3f(0.5) - (h - vec3f(0.5)) * 0.25);
  let stone = mix(1.0, 1.0 - smoothstep(0.36, 0.48, seat), resolved);
  let n = normalize(s.normal);
  let facet = normalize(n + (h - vec3f(0.5)) * 1.1 * resolved * stone);
  r.normal = facet;
  r.roughness = mix(0.25, 0.12, stone);
  r.metallic = mix(0.9, 0.45, stone);
  r.albedo = vec4f(vec3f(0.92, 0.94, 0.97) * mix(0.55, 1.0, stone), 1.0);
  // the ice's own studio, mirrored by the facet: a broad soft box overhead and toward the lens,
  // a dimmer horizon band, a few stones catching it hard (a sparkle, per stone)
  let v = normalize(s.eye - s.world);
  let refl = reflect(-v, facet);
  let box = smoothstep(0.1, 0.7, refl.y) * 0.8 + smoothstep(0.35, 0.95, dot(refl, v)) * 0.6;
  let band = smoothstep(0.25, 0.0, abs(refl.y - 0.05)) * 0.35;
  let sparkle = select(0.0, 3.0, h.x > 0.93) * resolved;
  // an unresolved pavé averages its stones: a steady satin white
  let studio = mix(0.55, box + band + sparkle, resolved);
  r.emissive = vec3f(0.93, 0.97, 1.0) * p.ice * studio * mix(0.3, 1.0, stone);
  return r;
}

const HEAD_UV_PER_M: f32 = 0.9;
// the body's islands (torso 0.58, forearm 0.5, hand 0.48, upper arm 0.41 UV a metre, measured)
const BODY_UV_PER_M: f32 = 0.5;
// the luma of head.py's FACE_MEAN (0.27, 0.16, 0.105): the baked complexion's mean
const SKIN_LUMA: f32 = 0.179;
// pores ~0.7 mm apart; hair follicles ~0.8 mm apart (in UV cells)
const PORE_FREQ: f32 = 1587.3;
const HAIR_FREQ: f32 = 1388.9;
const HAIR_COLOUR: vec3f = vec3f(0.012, 0.009, 0.008);
// the face's centre line in v, and the eyes' line in u (brows above it), measured on the MPFB head's UV
const FACE_V: f32 = 0.5168;
const BROW_U: f32 = 0.83;

fn headHash4(c: vec2f, seed: u32) -> vec4f {
  let i = vec3i(vec3f(c, f32(seed)));
  return vec4f(unitFloat(hash3i(i, seed)), unitFloat(hash3i(i, seed + 101u)), unitFloat(hash3i(i, seed + 211u)), unitFloat(hash3i(i, seed + 307u)));
}

fn headSegment(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let ab = b - a;
  let t = clamp(dot(p - a, ab) / max(dot(ab, ab), 1e-6), 0.0, 1.0);
  return length(p - (a + ab * t));
}

// Hair coverage at uv (0..1): at most one hair per cell (a follicle ~0.8 mm from the next),
// present where the density allows, a stroke 2-3.5 cells long, thick at the root and thin at the
// tip. The beard grows down the face (+u in MakeHuman's layout); above the eyes (u < BROW_U) the
// brows grow out from the nose, along v, rising a little. HAIR_MEAN is the coverage these strokes
// average to, so the footprint fade does not change the beard's darkness.
fn hairCoverage(uv: vec2f, density: f32, freq: f32, onHead: bool) -> f32 {
  let q = uv * freq;
  let base = floor(q);
  let brow = onHead && uv.x < BROW_U;
  let out = select(-1.0, 1.0, uv.y > FACE_V);
  var cover = 0.0;
  for (var a = -4; a <= 1; a = a + 1) {
    for (var b = -1; b <= 1; b = b + 1) {
      // a hair reaches up to 3.5 cells from its root: the beard searches up the face (-u), a brow inwards along v
      let cell = base + select(vec2f(f32(a), f32(b)), vec2f(f32(b), f32(a) * out), brow);
      let h = headHash4(cell, 17u);
      if (h.x < density) {
        let root = cell + h.yz;
        let dir = select(normalize(vec2f(1.0, (h.w - 0.5) * 0.9)), normalize(vec2f(-0.35 + (h.w - 0.5) * 0.5, out)), brow);
        let length = 2.0 + 1.5 * h.y;
        let d = headSegment(q, root, root + dir * length);
        let along = clamp(dot(q - root, dir) / length, 0.0, 1.0);
        let width = mix(0.2, 0.07, along);
        cover = max(cover, 1.0 - smoothstep(width * 0.5, width, d));
      }
    }
  }
  return cover;
}

// Pores: one per cell at most, a round pit (Worley: the nearest pore of the 3x3 cells). Returns the
// pit depth (0..1) and its gradient in cell units (for the bump).
fn poreAt(uv: vec2f, freq: f32) -> vec3f {
  let q = uv * freq;
  let base = floor(q);
  var best = vec3f(0.0);
  for (var dy = -1; dy <= 1; dy = dy + 1) {
    for (var dx = -1; dx <= 1; dx = dx + 1) {
      let cell = base + vec2f(f32(dx), f32(dy));
      let h = headHash4(cell, 29u);
      if (h.x < 0.75) {
        let centre = cell + vec2f(0.15) + h.yz * 0.7;
        let radius = 0.18 + 0.14 * h.w;
        let v = q - centre;
        let d = length(v);
        let t = clamp(1.0 - d / radius, 0.0, 1.0);
        let depth = t * t * (3.0 - 2.0 * t);
        if (depth > best.x) {
          // d(depth)/dq = s'(t) * dt/dq, with dt/dq = -v / (d * radius)
          let slope = 6.0 * t * (1.0 - t) / max(d * radius, 1e-4);
          best = vec3f(depth, -v * slope);
        }
      }
    }
  }
  return best;
}

fn hairMean(density: f32) -> f32 {
  return 1.0 - exp(-density * 0.55);
}

fn headSkin(s: SurfaceIn, o: SurfaceOut) -> SurfaceOut {
  var r = o;
  // COLOR_0 alpha: the head's UV island carries 1 - density/2 (0.5..1), every other island BODY_CODE
  let body = s.tint.a < 0.375;
  let density = clamp(select((1.0 - s.tint.a) * 2.0, 1.0 - s.tint.a * 4.0, body), 0.0, 1.0);
  let base = s.albedo.rgb;
  // UV units per pixel, and how resolved the pores and the hairs are at this distance. The body's
  // islands are laid out at about half the head's UV scale, so its pores take a lower UV frequency.
  let uvPerM = select(HEAD_UV_PER_M, BODY_UV_PER_M, body);
  let poreFreq = PORE_FREQ * uvPerM / HEAD_UV_PER_M;
  let uvPx = s.footprint * uvPerM;
  let poreSeen = 1.0 - smoothstep(0.35, 0.9, uvPx * poreFreq);
  let hairFreq = HAIR_FREQ * uvPerM / HEAD_UV_PER_M;
  let hairSeen = 1.0 - smoothstep(0.3, 0.8, uvPx * hairFreq);
  let n = normalize(s.normal);
  // A frame for the bump: MakeHuman's head UV runs u DOWN the face and v across it (towards the
  // subject's right), so with the head upright, -u is world up and +v is the figure's right.
  // There is no tangent attribute; this frame turns with the normal, so a pore stays a pit as the head turns.
  let side = normalize(select(cross(vec3f(0.0, 1.0, 0.0), n), vec3f(1.0, 0.0, 0.0), abs(n.y) > 0.98));
  let up = cross(n, side);
  let pore = poreAt(s.uv, poreFreq);
  let pit = pore.x * poreSeen;
  // the pit's slope in world terms (per cell -> a tilt); a pit tilts the normal towards its centre
  // and a finer-than-the-bake unevenness (2-5 mm): a height field's gradient in the same frame
  let fineScale = poreFreq * 0.3;
  let fine = detailFbm(vec3f(s.uv * fineScale, 5.0), 3, uvPx * fineScale);
  // the body's islands are not laid out like the head's, so its frame is only roughly right: a gentler bump
  let bump = select(1.0, 0.45, body);
  let slope = ((-up * pore.y - side * pore.z) * 0.035 * poreSeen + (-up * fine.gradient.x - side * fine.gradient.y) * 0.012) * bump;
  let blotch = detailFbm(vec3f(s.uv * poreFreq * 0.08, 2.0), 3, uvPx * poreFreq * 0.08);
  var albedo = base * (1.0 - select(0.22, 0.12, body) * pit) * (0.94 + 0.12 * blotch.value);
  // oil: on the face, the lighter, raised planes (nose, forehead, cheekbones) are glossier; the
  // body is drier and broader in its sheen (no plastic hot spot under a hard key); pores are dull
  let luma = dot(base, vec3f(0.2126, 0.7152, 0.0722));
  let oily = clamp(0.47 - 1.2 * (luma - SKIN_LUMA), 0.36, 0.6);
  var rough = clamp(select(oily, 0.6, body) + 0.15 * pit + 0.08 * (blotch.value - 0.5) + 0.1 * (fine.value - 0.5), 0.34, 0.7);
  var normal = normalize(n + slope - n * dot(slope, n));
  // the hairs, or their average darkness where they are finer than a pixel
  let cover = select(0.0, hairCoverage(s.uv, density, hairFreq, !body), hairSeen > 0.0 && density > 0.02);
  let mean = hairMean(density);
  let hair = mix(mean, cover, hairSeen);
  albedo = mix(albedo, HAIR_COLOUR, hair * 0.92);
  rough = mix(rough, 0.55, hair);
  r.albedo = vec4f(albedo, 1.0);
  r.roughness = rough;
  r.metallic = 0.0;
  r.normal = normal;
  return r;
}

// MakeHuman's eye texture holds two eyes; their iris centres and radii, measured on the PNG. glTF UVs run v DOWN
// (the exporter flips Blender's v), which is the PNG's own row order.
const IRIS_A: vec2f = vec2f(0.703, 0.298);
const IRIS_B: vec2f = vec2f(0.288, 0.708);
const IRIS_R: f32 = 0.113;
const PUPIL_R: f32 = 0.036;

fn headEye(s: SurfaceIn, o: SurfaceOut) -> SurfaceOut {
  var r = o;
  let da = s.uv - IRIS_A;
  let db = s.uv - IRIS_B;
  let d2 = select(db, da, dot(da, da) < dot(db, db));
  let d = length(d2);
  let angle = atan2(d2.y, d2.x);
  let aa = max(s.footprint * 4.0, 0.004);
  // the iris: dark brown, radial fibres, a darker collarette and a dark limbal ring
  let fibres = 0.75 + 0.5 * detailNoise(vec3f(angle * 18.0, d * 40.0, 0.0)).value;
  var iris = vec3f(0.1, 0.05, 0.024) * fibres;
  iris = iris * mix(0.6, 1.0, smoothstep(PUPIL_R, PUPIL_R * 1.8, d));
  iris = iris * mix(1.0, 0.35, smoothstep(IRIS_R * 0.8, IRIS_R, d));
  let inIris = 1.0 - smoothstep(IRIS_R - aa, IRIS_R + aa, d);
  let inPupil = 1.0 - smoothstep(PUPIL_R - aa, PUPIL_R + aa, d);
  // the sclera from the bake, a little shadowed and warm, never paper white
  let sclera = s.albedo.rgb * vec3f(0.62, 0.58, 0.55);
  var albedo = mix(sclera, iris, inIris);
  albedo = mix(albedo, vec3f(0.004), inPupil);
  r.albedo = vec4f(albedo, 1.0);
  r.roughness = 0.03;
  r.metallic = 0.0;
  return r;
}

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceDefaults(s);
  let c = classOf(s);
  switch c {
    case 1u: { return floorSurface(s, p, o); }
    case 2u: { return brickSurface(s, o); }
    case 4u: { o.emissive = s.emissive * p.tubeGain; }
    case 10u, 13u: { return clearCoat(s, p, o, 0.035); }
    case 11u: {
      // The hero's SATIN SILVER (T1407b wide, round 4). As a 0.85-metallic mirror it showed only
      // the black room and read near-black in every wide; the reference hero is a light satin
      // grey that takes the set's low keys on its bumper and bonnet. A light, mostly dielectric
      // albedo with a broad sheen does that. (The title keeps its own matte grey, title.ts.)
      o.albedo = vec4f(vec3f(p.silverAlbedo) * vec3f(0.98, 1.0, 1.02), 1.0);
      o.metallic = p.silverMetallic;
      return clearCoat(s, p, o, p.silverRoughness);
    }
    case 12u: { return clearCoat(s, p, o, 0.42); }
    case 14u, 19u: { o.roughness = 0.035; o.metallic = 1.0; }
    case 15u: { o.roughness = 0.015; o.metallic = 0.0; }
    case 17u: {
      let n = detailFbm(s.world * 40.0, 3, s.footprint);
      o.roughness = 0.65 + 0.2 * n.value;
      o.normal = detailBump(s.normal, n.gradient * 0.002, 1.0);
    }
    case 18u: { o.emissive = s.emissive * p.headGain; }
    case 20u: { o.emissive = s.emissive * p.tailGain; }
    case 30u: {
      let luma = dot(o.albedo.rgb, vec3f(0.2126, 0.7152, 0.0722));
      o.albedo = vec4f(mix(vec3f(luma), o.albedo.rgb, 0.6), 1.0);
      o.roughness = 0.45;
    }
    case 31u, 32u: {
      let n = detailFbm(s.world * 55.0, 3, s.footprint);
      o.roughness = 0.9;
      o.normal = detailBump(s.normal, n.gradient * 0.0012, 1.0);
    }
    case 35u: { return jewel(s, p, o); }
    case 36u: { return headSkin(s, o); }
    case 37u: { return headEye(s, o); }
    case 40u: { o.albedo = vec4f(vec3f(p.cycAlbedo), 1.0); o.roughness = 0.95; o.metallic = 0.0; }
    default: {}
  }
  return o;
}
